using System.Security.Cryptography;
using chatxp.core;
using Xunit;

namespace chatxp.Core.Tests;

/// <summary>
/// Byte-compatibility tests against test vectors generated by the *actual Swift app crypto*
/// (chat/Encrypt.swift flow: CryptoKit P256.KeyAgreement + hkdfDerivedSymmetricKey +
/// AES.GCM.seal) run on this machine. If these pass, .NET-encrypted messages are readable
/// by the iOS app and vice-versa.
/// Vectors stored as flat files in the repo under TestVectors/ (generated by gen.swift,
/// single-line base64) to avoid hand-copy errors.
/// Generator source: /tmp/hkdf_probe/gen3.swift — copy back into TestVectors/ if regenerated.
/// </summary>
public class CryptoVectorTests
{
    private static readonly string VectorsDir =
        Path.Combine(AppContext.BaseDirectory, "TestVectors");

    private static string ReadVector(string name) =>
        File.ReadAllText(Path.Combine(VectorsDir, name)).Trim();

    // Fixed private scalars used by gen3.swift.
    private static byte[] AliceScalar => Enumerable.Range(0, 32).Select(i => (byte)(i & 0xFF)).ToArray();
    private static byte[] BobScalar =>
        new byte[] { 0xDE, 0xAD, 0xBE, 0xEF }.Concat(Enumerable.Range(0, 28).Select(i => (byte)(i & 0xFF))).ToArray();

    private static string AlicePub => ReadVector("vec_alice_pub.b64");
    private static string BobPub => ReadVector("vec_bob_pub.b64");
    private static string SymmetricKey => ReadVector("vec_key.b64");
    private static string SwiftCiphertext => ReadVector("vec_ct.b64");
    private const string SwiftPlaintext = "interop-test-message";

    [Fact]
    public void PublicKeys_Match_SwiftVectors()
    {
        // Given the same private scalar, .NET must derive the identical rawRepresentation
        // (X || Y, 64 bytes) as CryptoKit.
        var alice = E2eeCrypto.FromPrivateKey(AliceScalar);
        var bob = E2eeCrypto.FromPrivateKey(BobScalar);

        Assert.Equal(AlicePub, alice.Base64PublicKey);
        Assert.Equal(BobPub, bob.Base64PublicKey);
    }

    [Fact]
    public void HKDF_Matches_SwiftVector()
    {
        // Given the same two keys, HKDF must produce the identical symmetric key.
        var alice = E2eeCrypto.FromPrivateKey(AliceScalar);
        var key = alice.DeriveSymmetricKeyForTest(BobPub);
        Assert.Equal(SymmetricKey, Convert.ToBase64String(key));
    }

    [Fact]
    public void DotNet_Decrypts_SwiftCiphertext()
    {
        // A message sealed by CryptoKit AES.GCM.seal must open here with the peer's
        // rawRepresentation public key — proving iOS -> .NET direction.
        var bob = E2eeCrypto.FromPrivateKey(BobScalar);
        var decrypted = bob.Decrypt(SwiftCiphertext, AlicePub);
        Assert.Equal(SwiftPlaintext, decrypted);
    }

    [Fact]
    public void Encrypt_Uses_Fresh_Nonce_Per_Message()
    {
        var alice = E2eeCrypto.FromPrivateKey(AliceScalar);
        var bob = E2eeCrypto.FromPrivateKey(BobScalar);

        var first = alice.Encrypt(SwiftPlaintext, BobPub);
        var second = alice.Encrypt(SwiftPlaintext, BobPub);

        Assert.NotNull(first);
        Assert.NotNull(second);
        Assert.NotEqual(first, second);
        Assert.Equal(SwiftPlaintext, bob.Decrypt(first!, AlicePub));
        Assert.Equal(SwiftPlaintext, bob.Decrypt(second!, AlicePub));
    }

    [Fact]
    public void DotNet_Encrypts_Message_Swift_Can_Verify()
    {
        // .NET -> iOS direction, structurally: .NET encrypts with Alice's key towards Bob's
        // public key; Bob's key pair (same as Swift's Bob) must decrypt it. Since Swift's
        // Bob derives the same symmetric key (previous test), Swift decrypts it too.
        var alice = E2eeCrypto.FromPrivateKey(AliceScalar);
        var bob = E2eeCrypto.FromPrivateKey(BobScalar);

        var encrypted = alice.Encrypt(SwiftPlaintext, BobPub);
        Assert.NotNull(encrypted);
        Assert.Equal(SwiftPlaintext, bob.Decrypt(encrypted!, AlicePub));
    }
}
